// arch_neural_init — ativa o cérebro completo na ordem correta:
//   1. Importa anatomia salva (REGIÃO 14)
//   2. Ativa todos os módulos (REGIÕES 03-13)
//   3. Pronto pra v112_processar
// ═══════════════════════════════════════════════════════════════════
window.arch_neural_init = function(cerebro_externo){
  // 1. Importa cérebro (parâmetro externo OU embutido)
  const cerebro = cerebro_externo || window._ARCH_CEREBRO_JSON;
  if(cerebro){
    v112_importar(cerebro);
  }
  
  // 2. Ativa cada módulo (eval da string — eles se hookam no v112_processar atual)
  for(const m of (window._ARCH_MODULOS || [])){
    try {
      // eval com indireção pra escopo global
      (1,eval)(m.src);
    } catch(e){
      console.warn('[arch_neural_init] módulo "' + m.nome + '" erro:', e.message);
    }
  }
  
  // 3. Normaliza sub-redes pós-módulos
  if(window.V112 && window.V112.subredes){
    for(const [nome, sr] of Object.entries(window.V112.subredes)){
      if(sr && !Array.isArray(sr.satelites)) sr.satelites = [];
    }
  }
  
  return {
    sub_redes: Object.keys(window.V112.subredes).length,
    nodes: window.V112.nodes.length,
    pronto: true
  };
};

// Auto-init em Node.js (mas NÃO no browser — o browser pode querer customizar)
if(typeof module !== 'undefined' && module.exports){
  module.exports = {
    init: window.arch_neural_init,
    V112: window.V112,
    processar: function(input){ return window.v112_processar(input); }
  };
}

